+import type { Record } from "./project.ts";
+import { addRecord } from "./store.ts";
+
+export interface RecordSource {
+  load(repo: string): Promise<Record[]>;
+}
+
+const sources: RecordSource[] = [];
+
+export const registerSource = (source: RecordSource): void => {
+  sources.push(source);
+};
+
+export const loadRecords = async (repo: string): Promise<Record[]> => {
+  const allRecords: Record[] = [];
+
+  for (const source of sources) {
+    const records = await source.load(repo);
+    records.forEach(addRecord);
+    allRecords.push(...records);
+  }
+
+  return allRecords;
+};
+
+export const getSources = (): readonly RecordSource[] => [...sources];
