+export interface Record {
+  id: string;
+  path: string;
+  description: string;
+  context: string;
+}
+
+export const project = (records: readonly Record[]): string => {
+  if (records.length === 0) return "";
+
+  const header =
+    records.length === 1
+      ? "📚 Context: 1 related record"
+      : `📚 Context: ${records.length} related records`;
+
+  const items = records
+    .map(
+      (r) =>
+        `• [${r.id}] ${r.path}\n  ${r.description}\n  Context: ${r.context}`
+    )
+    .join("\n\n");
+
+  return `${header}\n\n${items}`;
+};
