@@ -0,0 +1,23 @@
+import type { Record } from "./project.ts";
+
+const records: Map<string, Record[]> = new Map();
+
+export const addRecord = (record: Record): void => {
+  const key = record.path;
+  if (!records.has(key)) {
+    records.set(key, []);
+  }
+  records.get(key)!.push(record);
+};
+
+export const getRecordsForPath = (filePath: string): readonly Record[] => {
+  return records.get(filePath) ?? [];
+};
+
+export const getAllRecords = (): readonly Record[] => {
+  return Array.from(records.values()).flat();
+};
+
+export const clearStore = (): void => {
+  records.clear();
+};
