+import { registerSource, loadRecords } from "../core/loader.ts";
+import { getContext, hasContext } from "../public/context.ts";
+import { readWithContext } from "../public/read-with-context.ts";
+import { MemoryRecordSource } from "../sources/memory-source.ts";
+
+async function exampleUsage() {
+  const repo = "/path/to/repo";
+  const filePath = "src/core/query.ts";
+
+  const source = new MemoryRecordSource();
+  source.addRecord({
+    id: "r-1a77e5",
+    path: filePath,
+    description: "Path-scoped injection to avoid whole-repo dumps",
+    context: "The hook resolves records for one path at tool invocation time",
+  });
+
+  registerSource(source);
+  await loadRecords(repo);
+
+  console.log("\n=== Pattern A: Explicit Context Fetching ===");
+  if (hasContext(repo, filePath)) {
+    const context = getContext(repo, filePath);
+    console.log("Context found:");
+    console.log(context);
+  }
+
+  console.log("\n=== Pattern B: Auto-Injected Read ===");
+  const result = readWithContext({ repo, filePath });
+  console.log("File content:");
+  console.log(result.content);
+  console.log("\nContext available?", result.hasContext);
+  if (result.context) {
+    console.log("Context:", result.context);
+  }
+
+  console.log("\n=== Usage in Agent (no hook support) ===");
+  console.log(`
+    Before reading a file in an agent without hook support:
+
+    1. Call: const context = getContext(repo, filePath);
+    2. If context is not null, append it to the response
+    3. User sees: [file content] + [context records]
+
+    This works for ANY editor/agent, no plugin needed.
+  `);
+}
+
+exampleUsage().catch(console.error);
