+import { recordsForPath } from "../core/inject.ts";
+import { project } from "../core/project.ts";
+
+export const getContext = (repo: string, filePath: string): string | null => {
+  return recordsForPath(repo, filePath);
+};
+
+export const hasContext = (repo: string, filePath: string): boolean => {
+  const context = getContext(repo, filePath);
+  return context !== null && context.length > 0;
+};
+
+export const formatContext = (context: string | null): string => {
+  if (!context) return "";
+  return `\n\n${context}`;
+};
