+import { getContext } from "./context.ts";
+
+interface ReadOptions {
+  repo: string;
+  filePath: string;
+  offset?: number;
+  limit?: number;
+}
+
+export interface ReadResult {
+  content: string;
+  context?: string;
+  hasContext: boolean;
+}
+
+export const readWithContext = (
+  options: ReadOptions
+): ReadResult => {
+  const { repo, filePath } = options;
+
+  let content = `File: ${filePath}\n(content would be read here)`;
+
+  const context = getContext(repo, filePath);
+  const hasContext = context !== null && context.length > 0;
+
+  return {
+    content,
+    context: context ?? undefined,
+    hasContext,
+  };
+};
+
+export const readAndInjectContext = (
+  options: ReadOptions
+): string => {
+  const result = readWithContext(options);
+
+  if (!result.hasContext) {
+    return result.content;
+  }
+
+  return `${result.content}\n\n${"=".repeat(60)}\n${result.context}`;
+};
