+import type { RecordSource } from "../core/loader.ts";
+import type { Record } from "../core/project.ts";
+
+export class MemoryRecordSource implements RecordSource {
+  private records: Record[] = [];
+
+  addRecord(record: Record): void {
+    this.records.push(record);
+  }
+
+  async load(): Promise<Record[]> {
+    return [...this.records];
+  }
+
+  clear(): void {
+    this.records = [];
+  }
+}
